parameters.jsCode:
const manifest = $input.first().json;
const intent = $('Intent Webhook').isExecuted ? ($('Intent Webhook').first().json.body || {}) : {};
const wantAll = intent.action === 'gather-all';
const tiers = wantAll ? ['core','tooling','personal','upstream'] : ['core','tooling'];
return manifest.repos
  .filter(r => tiers.includes(r.tier))
  .map(r => ({ json: { ...r, localName: `${r.owner}--${r.name}`, intent } }));

parameters.jsonBody:
={{ JSON.stringify({
  clone_addr: `https://github.com/${$json.owner}/${$json.name}.git`,
  repo_name: $json.localName,
  repo_owner: $env.FORGEJO_OWNER,
  description: $json.role,
  mirror: true,
  mirror_interval: '8h0m0s',
  private: $json.visibility === 'private',
  service: 'github',
  wiki: true, issues: true, releases: true,
  ...($env.GITHUB_TOKEN ? { auth_token: $env.GITHUB_TOKEN } : {})
}) }}

parameters.jsCode:
const manifest = $('Fetch Manifest').first().json;
const repos = $('Split Repos').all().map(i => i.json);
const results = $input.all().map(i => i.json);
const mirrored = results.filter(r => r && r.id).length;
const intent = repos[0]?.intent || {};
let inv = null;
try { const j = $('Fetch Local Inventory').first().json; if (j && j.repos) inv = j; } catch {}
let goog = null;
try { const j = $('Fetch Google Inventory').first().json; if (j && j.items) goog = j; } catch {}
let googleTable = '(no Google inventory yet)';
if (goog) {
  const t = goog.totals;
  const code = goog.items.filter(i => i.kind === 'code' || i.kind === 'video').slice(0, 300).map(i => `- ${(i.born||'').slice(0,10)} | ${i.source} ${i.name} | ${i.kind}`).join('\n');
  const years = (goog.byYear||[]).map(y => `${y.year}:${y.files}`).join(' ');
  googleTable = `Totals: ${t.drive} Drive files (${t.docs} docs, ${t.code} code, ${t.audio} audio), ${t.youtube} YouTube uploads${goog.gmail ? `, ${goog.gmail.messagesTotal} Gmail messages` : ''}. Files born per year: ${years}\n${code}`;
}
const byDate = [...repos].sort((a,b) => (a.createdAt||'').localeCompare(b.createdAt||''));
const ghTable = byDate.map(r => `- ${r.createdAt} → ${r.pushedAt} | GitHub ${r.owner}/${r.name} | ${r.tier} | ${r.brand || '-'} | ${r.role}`).join('\n');
let localTable = '(no local inventory yet — run scripts/gather-local.sh on the M2 Ultra)';
if (inv) {
  const src = p => p.startsWith('/Volumes/') ? 'HDD:' + p.split('/')[2] : inv.host.toUpperCase();
  const lr = (inv.repos||[]).filter(r => !/github\.com[/:](RSPNOIZY|Noizyfish)\//i.test(r.remote||''))
    .map(r => ({ d: (r.firstCommit||r.oldestFileBorn||r.born||'').slice(0,10), t: `${src(r.path)} ${r.path} | git ${r.commits} commits${r.remote?'':' NO REMOTE'}${r.dirty?' dirty':''}` }));
  const lp = (inv.looseProjects||[]).map(p => ({ d: (p.oldestFileBorn||p.born||p.modified||'').slice(0,10), t: `${src(p.path)} ${p.path} | loose ${p.marker}` }));
  const docs = (inv.docs||[]).map(d => `- docs ${d.root}: ${d.count} files, born ${(d.oldestFileBorn||'?').slice(0,10)} → ${(d.newestFileBorn||'?').slice(0,10)}`).join('\n');
  localTable = [...lr, ...lp].sort((a,b) => a.d.localeCompare(b.d)).map(x => `- ${x.d} | ${x.t}`).join('\n') + '\n' + docs;
}
const question = intent.question ? `\n\nThe founder asks: ${intent.question}` : '';
const prompt = `You are GABRIEL, orchestrator for the MC96ECO Universe / NOIZY Empire (canon: noizy.ai, covenant 75/25, killSwitchHolder RSP_001).

The founder has ~30 years of work (${manifest.archiveStart || '1996'} → today) on GitHub, Google (Drive, YouTube, Gmail), an M2 Ultra and external drives, with an intense vibe-coding era since ${manifest.storyStart || 'late 2025'}. Everything below is dated by repo creation, first commit, or file BIRTH date. Colour in the whole story in strict chronological order: year-by-year for the archive, month-by-month for the vibe-coding era. Explain what was being built, how the pieces connect, what is duplicated, abandoned, or only on a drive with no remote, and the 5 most valuable next moves to converge it all. Be direct and concrete. Always write the brand as NOIZY (never with an S). Markdown sections: ## The Story (chronological), ## How It Connects, ## Duplicates, Dead Ends & Unbacked Work, ## Next 5 Moves.${question}

GitHub (created → last push | repo | tier | brand | role):
${ghTable}

Local — M2 Ultra + drives (birth date | source path | kind):
${localTable}

Google — Drive + YouTube + Gmail (birth date | item | kind):
${googleTable}`;
return [{ json: { prompt, repoCount: repos.length, mirrored, intent, localRepos: inv ? inv.totals.repos : 0 } }];

