  model: $env.ANTHROPIC_MODEL || 'claude-sonnet-4-6',
  max_tokens: 4096,
  messages: [{ role: 'user', content: $json.prompt }]
}) }}

parameters.jsCode:
const res = $input.first().json;
const meta = $('Build Prompt').first().json;
const text = (res.content || []).filter(c => c.type === 'text').map(c => c.text).join('\n');
const date = new Date().toISOString().slice(0,10);
return [{ json: {
  ok: true,
  date,
  title: `Thru-Line digest ${date}`,
  body: `${text}\n\n---\n_${meta.repoCount} GitHub repos + ${meta.localRepos} local repos scanned · ${meta.mirrored} mirrors created this run · model ${res.model}_`,
  digest: text,
  repoCount: meta.repoCount,
  mirrored: meta.mirrored,
  fromIntent: $('Intent Webhook').isExecuted
} }];
